_ = PInvoke.ShowWindow(hWnd, SHOW_WINDOW_CMD.SW_SHOW);

if (!PInvoke.SetForegroundWindow(hWnd))
{
    Logger.LogWarning("Mouse Jump preview could not acquire the foreground window; dismissing this activation.");
    this.HideWindow();
    return;
}

// Only set focus/active state after foreground transfer succeeds.
TrySetFocusAndActiveWindow(hWnd);

using var foregroundApp = NotepadFixture.Start();
Assert.IsTrue(WindowControl.WaitForForeground(new IntPtr(foregroundApp.Window.WindowHandle), 5_000, 2));
Assert.IsTrue(NamedEventHelper.WaitAndSignal(NamedEventHelper.MouseJumpShowPreview, 10_000));
Assert.IsTrue(WaitForProcess(expected: true), "Foreground denial terminated Mouse Jump.");
KeyboardHelper.SendKeys(Key.LWin, Key.Shift, Key.D);
